 --   DECLARE @p_program_id			          NVARCHAR(100)			= N'SCP0106';
 --   DECLARE @p_sheet_name			          NVARCHAR(100)			= N'CURRENT';
 --   DECLARE @p_user_id				          NVARCHAR(30)			= N'iamarock';
 --   DECLARE @pebug_mode				          NVARCHAR(1)			= N'F';


	--DECLARE @test_mode                          NVARCHAR(20)		= N'F';
	DECLARE @test_mode                          NVARCHAR(20)	= N'T';


	DECLARE @V_ELAPSED_TIME_BEG     DATETIME                = CURRENT_TIMESTAMP;


	-- LOG 용 변수 설정
    DECLARE @v_program_name NVARCHAR(150)	= 'SCP0106_SAVE_CAPA_LOSS_PLAN_MODEL_ASSEMBLY';
    DECLARE @v_log_type     NVARCHAR(30); -- START/END/ERROR/...
    DECLARE @n_log_count    INTEGER			= 0;
    DECLARE @v_log_message  NVARCHAR(1000);
    DECLARE @v_description  NVARCHAR(500);
    DECLARE @d_event_date   DATETIME;


	-- 트렌젝션 시작
	BEGIN TRAN;

	BEGIN TRY
		-- 시작 LOG
		SET @v_log_type						= 'START';
		SET @v_log_message					= '########## Start of procedure ##########';
		SET @v_description					= '';
		SET @d_event_date					= SYSDATETIME();

        IF @test_mode <> 'T'
        BEGIN
		    EXEC PR_SCM_SYS_LOG_BATCH @v_program_name, @v_log_type, @n_log_count, @v_log_message, @v_description, @d_event_date;
        END


		DECLARE @v_delimiter				NVARCHAR(1) = '^'

		DECLARE @v_all_cnt		        INTEGER		= 0;
		DECLARE @v_cnt					INTEGER		= 0;

		SET @v_all_cnt = [dbo].[SCM_ARR_SPL_CNT](@p_division_id, @v_delimiter);

        PRINT CONCAT('@v_all_cnt : ', @v_all_cnt);


        PRINT N'속도 이슈로 Unpivot 을 UI 에서 DB 로 이전 BEGIN *******************************************************************************************************'
        BEGIN
			IF OBJECT_ID('tempdb..#T_SCP0106_DATE_COLUMNS') IS NOT NULL
				DROP TABLE #T_SCP0106_DATE_COLUMNS;

			SELECT    NR
					, COLUMN_NAME
					, COLUMN_VALUE
			INTO    #T_SCP0106_DATE_COLUMNS
			FROM    (
						SELECT    A.TOKEN AS COLUMN_NAME
								, B.TOKEN AS COLUMN_VALUE
								, A.NR
						FROM   dbo.String_Split(@p_date_column_names, '^') A
							JOIN (SELECT TOKEN, NR FROM dbo.String_Split(@p_date_column_values, '^')) B ON
									A.NR = B.NR
					) A
			WHERE   1=1
				AND A.COLUMN_NAME <> '';

			PRINT CONCAT('ELAPSED_TIME-#T_SCP0106_DATE_COLUMNS : ', CONVERT(VARCHAR, CURRENT_TIMESTAMP - @V_ELAPSED_TIME_BEG, 114));SET @V_ELAPSED_TIME_BEG = CURRENT_TIMESTAMP;

			--TESTING : NOK
			--select * from #T_SCP0106_DATE_COLUMNS;return;


			IF OBJECT_ID('tempdb..#T_SCP0106_DATE_VALUES_TEMP') IS NOT NULL
				DROP TABLE #T_SCP0106_DATE_VALUES_TEMP;

			SELECT    CONVERT(INT, NULL)            AS ROW_NR
					, CONVERT(INT, NULL)            AS COL_NR
					, CONVERT(NVARCHAR(30),  NULL)  AS COL_NAME
					, CONVERT(NVARCHAR(100), NULL)  AS COL_VALUE
			INTO    #T_SCP0106_DATE_VALUES_TEMP
			WHERE   1<>1;

			IF CURSOR_STATUS('global','CUR_SCP0106_DATE_COLUMNS') >= -1
			BEGIN
				IF CURSOR_STATUS('global','CUR_SCP0106_DATE_COLUMNS') > -1
				BEGIN
					CLOSE CUR_SCP0106_DATE_COLUMNS
				END

				DEALLOCATE CUR_SCP0106_DATE_COLUMNS
			END

			DECLARE @v_nr                       INT                 = 0;
			DECLARE @v_column_names          	NVARCHAR(MAX)		= N'';
			DECLARE @v_column_values          	NVARCHAR(MAX)		= N'';

			DECLARE CUR_SCP0106_DATE_COLUMNS CURSOR FOR
			SELECT    NR
					, COLUMN_NAME
					, COLUMN_VALUE
			FROM    #T_SCP0106_DATE_COLUMNS;

			OPEN CUR_SCP0106_DATE_COLUMNS;
			FETCH NEXT FROM CUR_SCP0106_DATE_COLUMNS INTO @v_nr, @v_column_names, @v_column_values

			WHILE @@FETCH_STATUS = 0
			BEGIN
				INSERT INTO #T_SCP0106_DATE_VALUES_TEMP
				SELECT    A.ROW_NR
						, A.COL_NR
						, A.COL_NAME
						, B.COL_VALUE
				FROM    (
							SELECT    @v_nr             AS ROW_NR
									, NR                AS COL_NR
									, TOKEN             AS COL_NAME
							FROM    dbo.String_Split(@v_column_names, ';')
						) A
						JOIN
						(
							SELECT    @v_nr             AS ROW_NR
									, NR                AS COL_NR
									, TOKEN             AS COL_VALUE
							FROM    dbo.String_Split(@v_column_values, ';')
						) B ON
								A.ROW_NR = B.ROW_NR
							AND A.COL_NR = B.COL_NR
				WHERE   1=1
					AND COL_NAME IS NOT NULL AND COL_NAME <> ''

				FETCH NEXT FROM CUR_SCP0106_DATE_COLUMNS INTO @v_nr, @v_column_names, @v_column_values
			END

			CLOSE CUR_SCP0106_DATE_COLUMNS;
			DEALLOCATE CUR_SCP0106_DATE_COLUMNS;

			PRINT CONCAT('ELAPSED_TIME-#T_SCP0106_DATE_VALUES_TEMP : ', CONVERT(VARCHAR, CURRENT_TIMESTAMP - @V_ELAPSED_TIME_BEG, 114));SET @V_ELAPSED_TIME_BEG = CURRENT_TIMESTAMP;

			--TESTING : NOK
			--select * from #T_SCP0106_DATE_VALUES_TEMP;return;


			IF OBJECT_ID('tempdb..#T_SCP0106_DATE_VALUES') IS NOT NULL
				DROP TABLE #T_SCP0106_DATE_VALUES;

			SELECT    A.ROW_NR
					, A.YYYYMM
					, A.COL_VALUE AS QTY
					--, B.COL_VALUE AS IPRV_GOL_RT	-- Improvement Rate 입력 영역을 제거하고 Operation Plan 에 Goal 직접 입력 형태로 수정(2025-02-06 mrchois) 
			INTO    #T_SCP0106_DATE_VALUES
			FROM    (
						SELECT    ROW_NR
                                , COL_NR
								, COL_NAME
								, COL_VALUE
								, REPLACE(REPLACE(REPLACE(COL_NAME, 'M_00', ''), 'M_01', ''), 'Y_', '') AS YYYYMM
						FROM    #T_SCP0106_DATE_VALUES_TEMP
						WHERE   1=1
							AND (SUBSTRING(COL_NAME, 3, 2) = '01' OR SUBSTRING(COL_NAME, 1, 2) = 'Y_')
					) A
					-- Improvement Rate 입력 영역을 제거하고 Operation Plan 에 Goal 직접 입력 형태로 수정(2025-02-06 mrchois) START
					--LEFT JOIN (
					--		        SELECT   ROW_NR
					--				        , COL_NR
					--				        , COL_NAME
					--				        , COL_VALUE
					--				        , REPLACE(REPLACE(REPLACE(COL_NAME, 'M_00', ''), 'M_01', ''), 'Y_', '') AS YYYYMM
					--		        FROM    #T_SCP0106_DATE_VALUES_TEMP
					--		        WHERE   1=1
					--			        AND SUBSTRING(COL_NAME, 3, 2) = '00'
					--) B ON
					--		A.ROW_NR = B.ROW_NR
					--	AND A.YYYYMM = B.YYYYMM;
					-- Improvement Rate 입력 영역을 제거하고 Operation Plan 에 Goal 직접 입력 형태로 수정(2025-02-06 mrchois) END

			PRINT CONCAT('ELAPSED_TIME-#T_SCP0106_DATE_VALUES : ', CONVERT(VARCHAR, CURRENT_TIMESTAMP - @V_ELAPSED_TIME_BEG, 114));SET @V_ELAPSED_TIME_BEG = CURRENT_TIMESTAMP;

