        BEGIN
		    IF OBJECT_ID('tempdb..#T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_BASE') IS NOT NULL
			    DROP TABLE #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_BASE;

