        BEGIN --데이터 저장 - 본테이블
            --월별 수치 저장
			MERGE INTO SCP_MST_CAPA_LOSS_PLAN_MDL A
			USING
			(
				SELECT	*
                FROM    #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL
                WHERE   1=1
					AND ISNULL(DIVISION_ID, '') <> ''
					AND ISNULL(COMPANY_ID, '') <> ''
					AND ISNULL(SITE_ID, '') <> ''
					AND ISNULL(PLANT_ID, '') <> ''
					AND ISNULL(FACTORY_ID, '') <> ''
					AND ISNULL(LINE_ID, '') <> ''
					AND ISNULL(OPERATION_ID, '') <> ''
					AND ISNULL(ELTR_LN_TP_CD, '') <> ''
					AND ISNULL(MDL_NM, '') <> ''
					AND ISNULL(MSR_GR_CD, '') <> ''
					AND ISNULL(MSR_TP_CD, '') <> ''
					AND ISNULL(YYYYMM, '') <> ''
			) B ON
			(
					A.DIVISION_ID			= B.DIVISION_ID
				AND A.COMPANY_ID			= B.COMPANY_ID
				AND A.SITE_ID				= B.SITE_ID
				AND A.PLANT_ID				= B.PLANT_ID
				AND A.FACTORY_ID			= B.FACTORY_ID
				AND A.LINE_ID				= B.LINE_ID
				AND A.OPERATION_ID			= B.OPERATION_ID
				AND A.ELTR_LN_TP_CD			= B.ELTR_LN_TP_CD
				AND A.MDL_NM				= B.MDL_NM
				AND A.MSR_GR_CD				= B.MSR_GR_CD
				AND A.MSR_TP_CD				= B.MSR_TP_CD
				AND A.YYYYMM				= B.YYYYMM
			)
			WHEN MATCHED THEN
			UPDATE
			SET
				  --PFRSLT_NVL			= B.PFRSLT_NVL
				--, BASE_NVL				= B.BASE_NVL
				--  IPRV_GOL_RT			= B.IPRV_GOL_RT	-- Improvement Rate 입력 영역을 제거하고 Operation Plan 에 Goal 직접 입력 형태로 수정(2025-02-06 mrchois)
				--, 
				  MSR_NVL				= B.MSR_NVL
				, LAST_UPDATED_BY		= B.LAST_UPDATED_BY
				, LAST_UPDATE_DATE		= B.LAST_UPDATE_DATE;

			MERGE INTO SCP_MST_CAPA_LOSS_PLAN_MDL A
			USING
			(
				SELECT	*
                FROM    #T_SCP0106_SCP_MST_CAPA_LOSS_PLAN_MDL_BASE
			) B ON
			(
					A.DIVISION_ID			= B.DIVISION_ID
				AND A.COMPANY_ID			= B.COMPANY_ID
				AND A.SITE_ID				= B.SITE_ID
				AND A.PLANT_ID				= B.PLANT_ID
				AND A.FACTORY_ID			= B.FACTORY_ID
				AND A.LINE_ID				= B.LINE_ID
				AND A.OPERATION_ID			= B.OPERATION_ID
				AND A.ELTR_LN_TP_CD			= B.ELTR_LN_TP_CD
				AND A.MDL_NM				= B.MDL_NM
				AND A.MSR_GR_CD				= B.MSR_GR_CD
				AND A.MSR_TP_CD				= B.MSR_TP_CD
			)
			WHEN MATCHED THEN
			UPDATE
			SET
				  ----PFRSLT_NVL			= B.PFRSLT_NVL
				  BASE_NVL				= B.BASE_NVL
				, LAST_UPDATED_BY		= B.LAST_UPDATED_BY
				, LAST_UPDATE_DATE		= B.LAST_UPDATE_DATE;

		END --데이터 저장 - 본테이블

